          {
            "name": "request",
            "description": "what this request is about",
            "required": true
          }
        ],
        "acceptance": [
          {
            "text": "The deliverable is markdown, has at most 350 words as counted by read (this is the one-page limit), and a title line naming the 2026-10-05 meeting.",
            "from_tasks": [
              "20261029T122710588867-root-c1b8",
              "20261029T123457206032-root-cabf",
              "20261029T125747104778-root-4a85"
            ]
          },
          {
            "text": "It contains one markdown table with exactly the columns Owner | Action | Due, and no other sections (no decisions, no summary).",
            "from_tasks": [
              "20261029T122710588867-root-c1b8",
              "20261029T123457206032-root-cabf",
              "20261029T125747104778-root-4a85"
            ]
          },
          {
            "text": "Every action item in the notes file is a row, including those stated in prose: Priya, Dev, Sam, Marta, Lee (5 of 5), and no row that is not in the notes.",
            "from_tasks": [
              "20261029T122710588867-root-c1b8",
              "20261029T123457206032-root-cabf",
              "20261029T125747104778-root-4a85"
            ]
          },
          {
            "text": "Each Due value is an ISO date (YYYY-MM-DD) or 'none': Dev 2026-10-08, Priya 2026-10-09, Sam 2026-10-09, Marta 2026-10-14, Lee none.",
            "from_tasks": [
              "20261029T122710588867-root-c1b8",
              "20261029T123457206032-root-cabf",
              "20261029T125747104778-root-4a85"
            ]
          },
          {
            "text": "Each Owner value uses the name exactly as written in the notes.",
            "from_tasks": [
              "20261029T122710588867-root-c1b8",
              "20261029T123457206032-root-cabf",
              "20261029T125747104778-root-4a85"
            ]
          },
          {
            "text": "Rows are ordered by Due ascending with 'none' last, ties in the order of the notes.",
            "from_tasks": [
              "20261029T122710588867-root-c1b8",
              "20261029T123457206032-root-cabf",
              "20261029T125747104778-root-4a85"
            ]
          },
          {
            "text": "Every statement is traceable to 2026-10-05.md; nothing is invented.",
            "from_tasks": [
              "20261029T122710588867-root-c1b8",
              "20261029T123457206032-root-cabf",
              "20261029T125747104778-root-4a85"
            ]
          },
          {
            "text": "The lead's report states that every table row was compared with the notes file, with the count verified (n of m, n = m).",
            "from_tasks": [
              "20261029T122710588867-root-c1b8",
              "20261029T123457206032-root-cabf",
              "20261029T125747104778-root-4a85"
            ]
          }
        ],
        "deliverable": {
          "description": "<ASK THE USER: what one request produces>",
          "path": "<ASK THE USER: where it goes>"
        },
        "budget": 8
      }
    ]
  }
